/*
 * COSE421 Term Project - Maze Runner RC Car (improved)
 *
 * Hardware layout for this build:
 * - LD19 LiDAR (front-mounted): front / right / left wall distances. SERCOM2, 230400 bps.
 * - Rear ultrasonic sensor: rear collision avoidance during backward / stuck recovery.
 *     Echo edges detected by EIC interrupt (EXTINT0 on PA16).
 * - LIS2DH12 accelerometer over I2C (SERCOM3, PA22/PA23). Speed sampled every 200ms,
 *     I2C read driven by SERCOM3 interrupt.
 * - PC console / Tera Term on SERCOM5 (PB22/PB23), 115200 bps. Speed/distance CSV is streamed here.
 * - Motor PWM generated by TCC0 (PA18 = left enable WO[2], PA19 = right enable WO[3]).
 *
 * Project requirement notes:
 * - Ultrasonic echo transition uses interrupt (EIC), not polling.
 * - Accelerometer I2C read uses interrupt (SERCOM3).
 * - PWM for motor control uses a Timer/Counter (TCC0).
 * - Speed is measured every 200ms and streamed as CSV over SERCOM5 for graphing.
 * - turn_count is tracked; after 5 turns a marker line is emitted so the PC log
 *   can be cut and the speed graph drawn.
 * - LiDAR sensor does NOT use interrupt (allowed by the spec); it is polled in main.
 */

#pragma GCC target ("thumb")

#include <stdint.h>
#include "sam.h"

/* Set to 1 when the SERCOM5 cable goes to HC-06 (9600). 0 = PC console (115200). */
#define USE_BLUETOOTH_OUTPUT 0

/* =========================
 * LD19 LiDAR packet format
 * ========================= */
#define PKG_HEADER          0x54
#define PKG_VER_LEN         0x2C
#define POINT_PER_PACK      12
#define LIDAR_PACKET_LEN    47

#define ANGLE_FULL          36000      /* 360.00 degree */
#define ANGLE_FRONT         27000      /* Adjust to match LiDAR mounting orientation */
#define ANGLE_RIGHT         0
#define ANGLE_LEFT          18000
#define ANGLE_TOLERANCE     500        /* +/- 5 degree window */

#define UNKNOWN_CM          999
#define LIDAR_STALE_MS      700
#define LIDAR_WAIT_STATUS_MS 1000       /* if any required LiDAR value is UNKNOWN, stop and wait */

/* Moving/median filter depth for LiDAR distances (excludes UNKNOWN_CM samples) */
#define FILTER_SIZE         3

/* =========================
 * Rear ultrasonic sensor pins
 * ========================= */
#define TRIG_PIN            17         /* PA17: rear ultrasonic trigger */
#define ECHO_PIN            16         /* PA16 / EXTINT0: rear ultrasonic echo */
#define TRIG_MASK           (0x1ul << TRIG_PIN)

#define REAR_BLOCKED_CM     10         /* Do not move backward if rear wall is closer than this */
#define REAR_SAFE_CM        15         /* Rear distance considered safe for backward movement */
#define US_TIMEOUT_MS       40         /* Echo considered lost after this long (no wall within range) */

/* =========================
 * LIS2DH12 accelerometer over I2C / SERCOM3
 * ========================= */
#define LIS2DH_ADDR              0x18
#define LIS2DH_ADDR_WRITE        0x30     /* (0x18 << 1) | 0 */
#define LIS2DH_ADDR_READ         0x31     /* (0x18 << 1) | 1 */
#define LIS2DH_WHO_AM_I          0x0F
#define LIS2DH_CTRL_REG1         0x20
#define LIS2DH_CTRL_REG4         0x23
#define LIS2DH_TEMP_CFG_REG      0x1F
#define LIS2DH_OUT_X_L           0x28

#define ACCEL_PERIOD_MS          200      /* Requirement: measure speed every 200ms */
#define ACCEL_BUF_SIZE           6
#define ACCEL_CALIB_SAMPLES      10
#define ACCEL_DEADBAND_MG        40
#define ACCEL_SPEED_MAX_CMS      300

#define I2C_STATE_IDLE           0
#define I2C_STATE_SEND_REG       1
#define I2C_STATE_SEND_READ_ADDR 2
#define I2C_STATE_READING        3

/* =========================
 * Motor pins
 * ========================= */
#define LEFT_IN1_PIN        6
#define LEFT_IN2_PIN        7
#define RIGHT_IN1_PIN       8
#define RIGHT_IN2_PIN       9

#define LEFT_IN1_MASK       (0x1ul << LEFT_IN1_PIN)
#define LEFT_IN2_MASK       (0x1ul << LEFT_IN2_PIN)
#define RIGHT_IN1_MASK      (0x1ul << RIGHT_IN1_PIN)
#define RIGHT_IN2_MASK      (0x1ul << RIGHT_IN2_PIN)
#define MOTOR_DIR_MASK      (LEFT_IN1_MASK | LEFT_IN2_MASK | RIGHT_IN1_MASK | RIGHT_IN2_MASK)

#define PWM_PERIOD          1000

#define SPEED_STOP          0
#define SPEED_LOW           300
#define SPEED_MID           600
#define SPEED_HIGH          900
#define SPEED_MAX           900
#define SPEED_MIN           100
#define SPEED_STEP          100
#define TURN_DELTA          150

/*
 * PWM pins: PA22/PA23 are reserved for I2C SDA/SCL.
 * PA18/PA19 are used as TCC0 outputs so left/right duty can be controlled independently.
 * PA18 = TCC0/WO[2] (left enable), PA19 = TCC0/WO[3] (right enable).
 */
#define LEFT_PWM_PIN        18
#define RIGHT_PWM_PIN       19

#define DIR_STOP            0
#define DIR_FORWARD         1
#define DIR_BACKWARD        2

#define MODE_STOP           0
#define MODE_FORWARD        1
#define MODE_BACKWARD       2
#define MODE_LEFT           3
#define MODE_RIGHT          4

/* =========================
 * Right-hand wall following tuning
 * ========================= */
#define WALL_TARGET_CM      18     /* desired distance to the right wall */
#define WALL_BAND_CM        5      /* dead-band around target before correcting */
#define FRONT_BLOCK_CM      15     /* front considered blocked below this */
#define FRONT_SLOW_CM       30     /* slow down below this */
#define SIDE_OPEN_CM        30     /* a side is "open" (turnable) above this */
#define DEADEND_SIDE_CM     20     /* both sides closed below this -> dead end */

/* Maneuver durations in ms (tune on the real car) */
#define HARD_TURN_MS        450
#define PIVOT_180_MS        900
#define BACKUP_MS           500

/* =========================
 * Timing intervals
 * ========================= */
#define ULTRASONIC_PERIOD_MS 120
#define STATUS_PERIOD_MS     2000

/* =========================
 * Baud values with 8MHz SERCOM reference clock
 * BAUD = 65536 * (1 - 16 * fbaud / fref)
 * ========================= */
#define BAUD_9600           0xFB15
#define BAUD_115200         0xC504
#define BAUD_230400         0x8A09

#if USE_BLUETOOTH_OUTPUT
#define CONSOLE_BAUD        BAUD_9600
#else
#define CONSOLE_BAUD        BAUD_115200
#endif

/* =========================
 * LD19 structs
 * ========================= */
typedef struct {
    uint16_t distance;
    uint8_t intensity;
} LiDARPointTypeDef;

typedef struct {
    uint8_t header;
    uint8_t ver_len;
    uint16_t speed;
    uint16_t start_angle;
    LiDARPointTypeDef point[POINT_PER_PACK];
    uint16_t end_angle;
    uint16_t timestamp;
    uint8_t crc8;
} LiDARFrameTypeDef;

